 38	const ALLOWED_HOSTS = new Set(["beminimalist.co", "www.beminimalist.co"]);
 39	
 40	export function parseMinimalistProductUrl(input: string) {
 41	  let url: URL;
 42	
 43	  try {
 44	    url = new URL(input.trim());
 45	  } catch {
 46	    throw new Error("Enter a complete Minimalist product URL.");
 47	  }
 48	
 49	  if (url.protocol !== "https:" || !ALLOWED_HOSTS.has(url.hostname)) {
 50	    throw new Error("For this prototype, use a beminimalist.co product URL.");
 51	  }
 52	
 53	  const match = url.pathname.match(/\/products\/([^/?#]+)/);
 54	  if (!match?.[1]) {
 55	    throw new Error("This does not look like a Minimalist product page.");
 56	  }
 57	
 58	  return {
 59	    canonicalUrl: `https://beminimalist.co/products/${match[1]}`,
 60	    handle: match[1],
 61	  };
 62	}
