  1	export type ProductCreative = {
  2	  sourceUrl: string;
  3	  title: string;
  4	  eyebrow: string;
  5	  headline: string;
  6	  supportingCopy: string;
  7	  badges: string;
  8	  detailLine: string;
  9	  price: string;
 10	  compareAtPrice?: string;
 11	  size: string;
 12	  cta: string;
 13	  imageUrl: string;
 14	};
 15	
 16	type ShopifyImage = {
 17	  src?: string;
 18	};
 19	
 20	type ShopifyVariant = {
 21	  title: string;
 22	  price: number;
 23	  compare_at_price?: number | null;
 24	  available: boolean;
 25	  featured_image?: ShopifyImage | null;
 26	};
 27	
 28	type ShopifyProduct = {
 29	  title: string;
 30	  tags?: string[];
 31	  price: number;
 32	  compare_at_price?: number | null;
 33	  featured_image?: string;
 34	  images?: string[];
 35	  variants?: ShopifyVariant[];
 36	};
 37	
 38	const ALLOWED_HOSTS = new Set(["beminimalist.co", "www.beminimalist.co"]);
 39	
 40	export function parseMinimalistProductUrl(input: string) {
 41	  let url: URL;
 42	
 43	  try {
 44	    url = new URL(input.trim());
 45	  } catch {
 46	    throw new Error("Enter a complete Minimalist product URL.");
 47	  }
 48	
 49	  if (url.protocol !== "https:" || !ALLOWED_HOSTS.has(url.hostname)) {
 50	    throw new Error("For this prototype, use a beminimalist.co product URL.");
 51	  }
 52	
 53	  const match = url.pathname.match(/\/products\/([^/?#]+)/);
 54	  if (!match?.[1]) {
 55	    throw new Error("This does not look like a Minimalist product page.");
 56	  }
 57	
 58	  return {
 59	    canonicalUrl: `https://beminimalist.co/products/${match[1]}`,
 60	    handle: match[1],
 61	  };
 62	}
 63	
 64	function decodeHtml(value: string) {
 65	  return value
 66	    .replaceAll("&amp;", "&")
 67	    .replaceAll("&quot;", '"')
 68	    .replaceAll("&#39;", "'")
 69	    .replaceAll("&lt;", "<")
 70	    .replaceAll("&gt;", ">");
 71	}
 72	
 73	function extractMetaDescription(html: string) {
 74	  const match = html.match(
 75	    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)["'][^>]*>/i,
 76	  );
 77	  return match?.[1] ? decodeHtml(match[1].trim()) : "";
 78	}
 79	
 80	function formatPrice(value: number | null | undefined) {
 81	  if (typeof value !== "number") return undefined;
 82	  return new Intl.NumberFormat("en-IN", {
 83	    style: "currency",
 84	    currency: "INR",
 85	    maximumFractionDigits: 0,
 86	  }).format(value / 100);
 87	}
 88	
 89	function deriveHeadline(tags: string[] = []) {
 90	  const normalized = tags.map((tag) => tag.toLowerCase());
 91	  const hasHydration = normalized.some((tag) =>
 92	    ["hydration", "moisturization"].includes(tag),
 93	  );
 94	  const hasRepair = normalized.some((tag) => tag.includes("repair"));
 95	  const hasSunCare = normalized.some((tag) => tag.includes("sun"));
 96	  const hasOilBalance = normalized.some((tag) => tag.includes("oil"));
 97	
 98	  if (hasHydration && hasRepair) return "Lightweight hydration.\nBarrier care.";
 99	  if (hasSunCare) return "Everyday sun protection.";
100	  if (hasOilBalance) return "Targeted care for oily skin.";
101	  if (hasHydration) return "Hydration for every day.";
102	  return "Ingredient-led care.\nMade transparent.";
103	}
104	
105	function deriveEyebrow(title: string) {
106	  return title
107	    .replace(/\s+(face\s+)?(moisturizer|moisturiser|serum|cleanser|sunscreen)$/i, "")
108	    .toUpperCase();
109	}
110	
111	function extractBadges(html: string) {
112	  const supportedLabels = [
113	    "Fragrance Free",
114	    "Non-comedogenic",
115	    "Essential Oil Free",
116	    "Silicone Free",
117	    "Sulphate Free",
118	  ];
119	  const found = supportedLabels.filter((label) =>
120	    html.toLowerCase().includes(label.toLowerCase()),
121	  );
122	  return found.slice(0, 2).join(" · ");
123	}
124	
125	function shortenCopy(description: string) {
126	  const firstSentence = description.split(/(?<=[.!?])\s/)[0] ?? description;
127	  if (firstSentence.length <= 145) return firstSentence;
128	  return `${firstSentence.slice(0, 141).trimEnd()}…`;
129	}
130	
131	function normalizeImageUrl(value: string) {
132	  const url = new URL(value.startsWith("//") ? `https:${value}` : value);
133	  if (url.hostname !== "cdn.shopify.com") {
134	    throw new Error("The product image did not come from the expected store CDN.");
135	  }
136	  url.searchParams.set("width", "1000");
137	  return url.toString();
138	}
139	
140	export async function fetchProductCreative(inputUrl: string): Promise<ProductCreative> {
141	  const { canonicalUrl, handle } = parseMinimalistProductUrl(inputUrl);
142	  const headers = { "User-Agent": "MinimalistAdStudio/0.1" };
143	  const [productResponse, pageResponse] = await Promise.all([
144	    fetch(`https://beminimalist.co/products/${handle}.js`, {
145	      headers,
146	      next: { revalidate: 3600 },
147	    }),
148	    fetch(canonicalUrl, { headers, next: { revalidate: 3600 } }).catch(() => null),
149	  ]);
150	
151	  if (!productResponse.ok) {
152	    throw new Error("Minimalist did not return product data for this URL.");
153	  }
154	
155	  const product = (await productResponse.json()) as ShopifyProduct;
156	  const pageHtml = pageResponse?.ok ? await pageResponse.text() : "";
157	  const selectedVariant =
158	    product.variants?.find((variant) => variant.available) ?? product.variants?.[0];
159	  const rawImage =
160	    selectedVariant?.featured_image?.src ?? product.featured_image ?? product.images?.[0];
161	
162	  if (!rawImage) throw new Error("No usable product image was found.");
163	
164	  const description = extractMetaDescription(pageHtml);
165	  const fallbackCopy = `${product.title}, presented with its ingredient concentration clearly stated.`;
166	
167	  return {
168	    sourceUrl: canonicalUrl,
169	    title: product.title,
170	    eyebrow: deriveEyebrow(product.title),
171	    headline: deriveHeadline(product.tags),
172	    supportingCopy: shortenCopy(description || fallbackCopy),
173	    badges: extractBadges(pageHtml),
174	    detailLine: product.title,
175	    price: formatPrice(selectedVariant?.price ?? product.price) ?? "",
176	    compareAtPrice: formatPrice(
177	      selectedVariant?.compare_at_price ?? product.compare_at_price,
178	    ),
179	    size: selectedVariant?.title ?? "",
180	    cta: "Explore product",
181	    imageUrl: normalizeImageUrl(rawImage),
182	  };
183	}
